(function(root){'use strict';const id=new URLSearchParams(location.search).get('handover');if(!id)return;const H=root.MT_HANDOVER,box=document.createElement('section');box.className='panel';box.id='exercise-transfer';const title=document.createElement('h2');title.textContent='Exercise values';const message=document.createElement('p');message.setAttribute('role','status');const apply=document.createElement('button'),back=document.createElement('button');apply.type=back.type='button';apply.textContent='Use the exercise values';back.textContent='Return current result to the answer';back.disabled=true;box.append(title,message,apply,back);document.querySelector('main').prepend(box);let item;
try{item=H.read(id);message.textContent='Load the exercise scenario, explore its result, then return the current numerical value to your answer. Other model parameters are stated assumptions of this scenario.';}catch(e){message.textContent=e.message;apply.disabled=true;return;}
apply.onclick=()=>{try{const t=item.target;if(t.kind==='calculator'){root.MT_STUDENT_API.apply(t.id,t.inputs);}else{const current=root.MT_LEARNING_CYCLE_CONTEXT.read();if(current.id!==t.id)throw Error('Open the matching experiment to use these values.');root.MT_MODEL_UI.restoreInputs(t.inputs);}back.disabled=false;message.textContent='Exercise values applied. The current result will be recalculated when returned.';}catch(e){message.textContent=e.message;}};
back.onclick=()=>{try{const t=item.target;let value;if(t.kind==='calculator'){const z=root.MT_STUDENT_API.result();if(z.id!==t.id||z.unit!==t.resultUnit)throw Error('The calculator result uses a different quantity or unit.');value=z.value;}else{const state=root.MT_MODEL_UI.state();if(!state||root.MT_LEARNING_CYCLE_CONTEXT.read().id!==t.id)throw Error('Calculate the matching model first.');if(t.metric)value=root.MT_MODEL_UI.evaluate(state.inputs).results[t.metric];else value=t.output.split('.').reduce((z,k)=>z?.[k],state.result);}H.returnValue(id,value*t.scale,t.unit);}catch(e){message.textContent=e.message;}};
})(window);
